import assert from "node:assert/strict";
import { describe, it, mock } from "node:test";
import {
  evaluateChequeForDeposit,
  getChequeHmacSecret,
  signChequePayload,
  verifyChequeSignature,
} from "./cheque-security";

const secret = "test-cheque-secret";

describe("cheque HMAC", () => {
  it("signs and verifies a payload", () => {
    const payload = {
      chequeId: "cabc123",
      amountCents: 12_000,
      payeeUserId: "user_1",
      expiresAtMs: Date.now() + 60_000,
    };
    const signature = signChequePayload(payload, secret);
    assert.equal(verifyChequeSignature(payload, signature, secret), true);
    assert.equal(
      verifyChequeSignature(
        { ...payload, amountCents: 12_001 },
        signature,
        secret,
      ),
      false,
    );
  });
});

describe("evaluateChequeForDeposit", () => {
  const base = {
    id: "c1",
    amountCents: 6000,
    payeeUserId: "payee",
    signature: "sig",
    status: "ISSUED" as const,
    expiresAt: new Date(Date.now() + 60_000),
  };

  it("accepts a valid issued cheque for the payee", () => {
    assert.equal(
      evaluateChequeForDeposit({
        instrument: base,
        depositAmountCents: 6000,
        depositorUserId: "payee",
        presentedSignature: "sig",
      }).ok,
      true,
    );
  });

  it("rejects double cash", () => {
    const result = evaluateChequeForDeposit({
      instrument: { ...base, status: "CLEARED" },
      depositAmountCents: 6000,
      depositorUserId: "payee",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /already cashed/i);
  });

  it("rejects payee mismatch", () => {
    const result = evaluateChequeForDeposit({
      instrument: base,
      depositAmountCents: 6000,
      depositorUserId: "someone-else",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /payee/i);
  });

  it("rejects amount mismatch", () => {
    const result = evaluateChequeForDeposit({
      instrument: base,
      depositAmountCents: 9000,
      depositorUserId: "payee",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /60\.00|90\.00/);
  });

  it("rejects presented signature tampering", () => {
    const result = evaluateChequeForDeposit({
      instrument: base,
      depositAmountCents: 6000,
      depositorUserId: "payee",
      presentedSignature: "tampered",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /tamper|signature/i);
  });

  it("rejects expired cheques", () => {
    const result = evaluateChequeForDeposit({
      instrument: {
        ...base,
        expiresAt: new Date(Date.now() - 1000),
      },
      depositAmountCents: 6000,
      depositorUserId: "payee",
      now: new Date(),
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /expired/i);
  });

  it("rejects voided cheques", () => {
    const result = evaluateChequeForDeposit({
      instrument: { ...base, status: "VOID" },
      depositAmountCents: 6000,
      depositorUserId: "payee",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /void/i);
  });

  it("rejects unknown statuses", () => {
    const result = evaluateChequeForDeposit({
      instrument: {
        ...base,
        status: "PENDING" as "ISSUED",
      },
      depositAmountCents: 6000,
      depositorUserId: "payee",
    });
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.reason, /cannot be deposited/i);
  });

  it("allows empty presented signatures", () => {
    assert.equal(
      evaluateChequeForDeposit({
        instrument: base,
        depositAmountCents: 6000,
        depositorUserId: "payee",
        presentedSignature: "",
      }).ok,
      true,
    );
  });

  it("re-checks HMAC when a secret is provided", () => {
    const expiresAt = new Date(Date.now() + 60_000);
    const payload = {
      chequeId: base.id,
      amountCents: base.amountCents,
      payeeUserId: base.payeeUserId,
      expiresAtMs: expiresAt.getTime(),
    };
    const signature = signChequePayload(payload, secret);
    assert.equal(
      evaluateChequeForDeposit({
        instrument: { ...base, signature, expiresAt },
        depositAmountCents: 6000,
        depositorUserId: "payee",
        hmacSecret: secret,
      }).ok,
      true,
    );

    const bad = evaluateChequeForDeposit({
      instrument: { ...base, signature: "deadbeef", expiresAt },
      depositAmountCents: 6000,
      depositorUserId: "payee",
      hmacSecret: secret,
    });
    assert.equal(bad.ok, false);
    if (!bad.ok) assert.match(bad.reason, /integrity/i);
  });
});

describe("verifyChequeSignature edges", () => {
  it("rejects length-mismatched signatures", () => {
    const payload = {
      chequeId: "c1",
      amountCents: 100,
      payeeUserId: "u",
      expiresAtMs: 1,
    };
    assert.equal(verifyChequeSignature(payload, "short", secret), false);
  });

  it("returns false when the timing-safe compare throws", () => {
    const payload = {
      chequeId: "c1",
      amountCents: 100,
      payeeUserId: "u",
      expiresAtMs: 1,
    };
    const signature = signChequePayload(payload, secret);
    const original = Buffer.from.bind(Buffer);
    mock.method(Buffer, "from", (...args: Parameters<typeof Buffer.from>) => {
      if (args[1] === "utf8") throw new Error("compare failed");
      return original(...args);
    });
    try {
      assert.equal(verifyChequeSignature(payload, signature, secret), false);
    } finally {
      mock.restoreAll();
    }
  });
});

describe("getChequeHmacSecret", () => {
  it("reads AUTH_SECRET", () => {
    const prev = process.env.AUTH_SECRET;
    process.env.AUTH_SECRET = "  reef-secret  ";
    try {
      assert.equal(getChequeHmacSecret(), "reef-secret");
    } finally {
      if (prev === undefined) delete process.env.AUTH_SECRET;
      else process.env.AUTH_SECRET = prev;
    }
  });

  it("throws when AUTH_SECRET is missing or blank", () => {
    const prev = process.env.AUTH_SECRET;
    delete process.env.AUTH_SECRET;
    try {
      assert.throws(() => getChequeHmacSecret(), /AUTH_SECRET/);
      process.env.AUTH_SECRET = "   ";
      assert.throws(() => getChequeHmacSecret(), /AUTH_SECRET/);
    } finally {
      if (prev === undefined) delete process.env.AUTH_SECRET;
      else process.env.AUTH_SECRET = prev;
    }
  });
});

import { createHmac, timingSafeEqual } from "node:crypto";

export const CHEQUE_SECURITY = {
  /** Issued cheques expire after 24h in the demo. */
  ttlMs: 24 * 60 * 60 * 1000,
  hmacAlgorithm: "sha256",
} as const;

export type ChequeSignPayload = {
  chequeId: string;
  amountCents: number;
  payeeUserId: string;
  /** Unix epoch milliseconds */
  expiresAtMs: number;
};

export function chequeCanonicalString(payload: ChequeSignPayload): string {
  return [
    payload.chequeId,
    String(payload.amountCents),
    payload.payeeUserId,
    String(payload.expiresAtMs),
  ].join("|");
}

export function signChequePayload(
  payload: ChequeSignPayload,
  secret: string,
): string {
  return createHmac(CHEQUE_SECURITY.hmacAlgorithm, secret)
    .update(chequeCanonicalString(payload))
    .digest("hex");
}

export function verifyChequeSignature(
  payload: ChequeSignPayload,
  signature: string,
  secret: string,
): boolean {
  const expected = signChequePayload(payload, secret);
  if (expected.length !== signature.length) return false;
  try {
    return timingSafeEqual(
      Buffer.from(expected, "utf8"),
      Buffer.from(signature, "utf8"),
    );
  } catch {
    return false;
  }
}

export type ChequeInstrumentSnapshot = {
  id: string;
  amountCents: number;
  payeeUserId: string;
  signature: string;
  status: "ISSUED" | "CLEARED" | "VOID";
  expiresAt: Date;
};

/** Pure rules for clearing a signed demo cheque (DB is source of truth). */
export function evaluateChequeForDeposit(input: {
  instrument: ChequeInstrumentSnapshot;
  depositAmountCents: number;
  depositorUserId: string;
  /** Signature embedded in the presented SVG/file, if any */
  presentedSignature?: string | null;
  /** Optional HMAC re-check when secret is available */
  hmacSecret?: string | null;
  now?: Date;
}): { ok: true } | { ok: false; reason: string } {
  const now = input.now ?? new Date();
  const { instrument } = input;

  if (instrument.status === "CLEARED") {
    return {
      ok: false,
      reason: "This cheque was already cashed (one-time use).",
    };
  }

  if (instrument.status === "VOID") {
    return { ok: false, reason: "This cheque has been voided." };
  }

  if (instrument.status !== "ISSUED") {
    return { ok: false, reason: "This cheque cannot be deposited." };
  }

  if (instrument.expiresAt.getTime() <= now.getTime()) {
    return {
      ok: false,
      reason: "This cheque has expired. Issue a new one and try again.",
    };
  }

  if (instrument.payeeUserId !== input.depositorUserId) {
    return {
      ok: false,
      reason: "Payee mismatch: only the named recipient can cash this cheque.",
    };
  }

  if (instrument.amountCents !== input.depositAmountCents) {
    return {
      ok: false,
      reason: `Cheque face is $${(instrument.amountCents / 100).toFixed(2)} but deposit amount is $${(input.depositAmountCents / 100).toFixed(2)}.`,
    };
  }

  if (
    input.presentedSignature != null &&
    input.presentedSignature.length > 0 &&
    input.presentedSignature !== instrument.signature
  ) {
    return {
      ok: false,
      reason: "Cheque signature does not match bank records (possible tampering).",
    };
  }

  if (input.hmacSecret) {
    const valid = verifyChequeSignature(
      {
        chequeId: instrument.id,
        amountCents: instrument.amountCents,
        payeeUserId: instrument.payeeUserId,
        expiresAtMs: instrument.expiresAt.getTime(),
      },
      instrument.signature,
      input.hmacSecret,
    );
    if (!valid) {
      return {
        ok: false,
        reason: "Cheque integrity check failed. Re-issue the cheque.",
      };
    }
  }

  return { ok: true };
}

export function getChequeHmacSecret(): string {
  const secret = process.env.AUTH_SECRET?.trim();
  if (!secret) {
    throw new Error("AUTH_SECRET is required to sign demo cheques.");
  }
  return secret;
}
